import sys; sys.path.insert(0,"/workspace/social/posts"); from build10 import build
B=r'''<style>.box p,.box li{font-size:20.5px;line-height:1.3}.box h2{font-size:23px;margin-bottom:4px}.tbl{font-size:18px}.note,.warn{font-size:17px}.tbl th,.tbl td{padding:2px 6px}.iq ol{font-size:19px;line-height:1.26}.pill{font-size:16px}.grid{gap:10px}.handle{bottom:-12px}.box{padding:9px 12px}.tagline{font-size:19px;margin-bottom:9px}.code{font-family:Consolas,'DejaVu Sans Mono',monospace;background:#f1f5f9;border:1px dashed #94a3b8;border-radius:6px;padding:5px 7px;margin:4px 0;line-height:1.3;font-size:16px}</style>
<div class="title">🔗 HxGN EAM OData Services <span class="badge">CHEAT SHEET</span></div>
<div class="tagline">REST with a data model: discover, query and update EAM records with plain HTTP. (HxGN EAM OData: Open Data Protocol, 12.3)</div>
<div class="grid">
<div class="box c1"><h2>1. What is OData?</h2><ul><li>Open Data Protocol: REST-based data services</li><li>Resources identified by URIs inside a data model</li><li>Core idea: the <b>Entity Data Model (EDM)</b></li><li>Supported in EAM since <b>12.1</b></li></ul></div>
<div class="box c2"><h2>2. Two discovery docs</h2><table class="tbl"><tr><th>Document</th><th>Gives you</th></tr><tr><td><b>Service doc</b><br>/axis/odataservices</td><td>All supported entity names + URLs (JSON)</td></tr><tr><td><b>Metadata</b><br>/$metadata</td><td>Properties, relationships, <b>&lt;Key&gt;</b> PropertyRefs (XML)</td></tr></table><div class="note">Both work without tenant or user credentials: no DB call.</div></div>
<div class="box c3"><h2>3. Operations = HTTP verbs</h2><table class="tbl"><tr><th>Op</th><th>Verb</th><th>Keys in URL?</th></tr><tr><td>Get Collection</td><td>GET</td><td>No</td></tr><tr><td>Get</td><td>GET</td><td>Yes</td></tr><tr><td>Add</td><td>POST</td><td>No</td></tr><tr><td>Sync (full)</td><td>PUT</td><td>Yes</td></tr><tr><td>Patch (partial)</td><td>PATCH</td><td>Yes</td></tr><tr><td>Delete</td><td>DELETE</td><td>Yes</td></tr></table></div>
<div class="box c4"><h2>4. Keys in the URL</h2><ul><li>Key names come from <b>$metadata</b></li><li>Strings in single quotes, numbers without</li></ul><div class="code">…/odataservices/Lots(<br>  LOTCODE='L1',<br>  ORGANIZATIONCODE='ORG1')<br>…/odataservices/Tasks(<br>  TASKCODE='TP1',TASKREVISION=0,<br>  ORGANIZATIONCODE='ORG1')</div></div>
<div class="box c5"><h2>5. Query options</h2><ul><li>Only on <b>Get Collection</b></li><li>Supported: <b>$filter $count $top $skip</b></li><li>Collection = entity's <b>default Dataspy</b></li></ul><div class="code">?$count=true  → "@odata.count"<br>?$top=3   → first 3 rows<br>?$skip=2  → from 3rd row on</div></div>
<div class="box c6"><h2>6. $filter syntax</h2><ul><li>eq ne gt ge lt le · and or not</li><li>contains / startswith / endswith</li></ul><div class="code">…/Lots?$filter=startswith(<br>  LOTID/ORGANIZATIONID/<br>  ORGANIZATIONCODE,'AOR')</div><div class="warn">No filters yet on DATETIME, QUANTITY, AMOUNT. Encode # as %23.</div></div>
<div class="box c7"><h2>7. Headers (Postman)</h2><div class="code">tenant       = &lt;TenantName&gt;<br>organization = &lt;ORGCODE&gt;<br>parentid     = &lt;CODE#ORG&gt;</div><ul><li>parentid only for <b>tab</b> entities</li><li>Credentials in the Authorization tab</li><li>Body JSON in, JSON out (like REST)</li></ul></div>
<div class="box c8"><h2>8. Date gotcha</h2><ul><li>YEAR must be <b>YYYY</b> in requests + responses</li><li>Epoch milliseconds are <b>not</b> supported</li></ul><div class="code">"COMMISSIONDATE": {<br>  "YEAR": 2025, "MONTH": 7, "DAY": 28,<br>  "HOUR": 0, ..., "TIMEZONE": "+0530" }</div></div>
<div class="box c1" style="grid-column:1 / span 2"><h2>9. Entities listed in the 12.3 brief</h2><table class="tbl"><tr><th>OData name</th><th>Screen (function)</th><th>OData name</th><th>Screen (function)</th></tr><tr><td>Assets</td><td>Assets (OSOBJA)</td><td>CaseManagements</td><td>Case Management (CSCASE)</td></tr><tr><td>Positions</td><td>Positions (OSOBJP)</td><td>CaseManagementTasks</td><td>Case Mgmt Tasks tab</td></tr><tr><td>Systems</td><td>Systems (OSOBJS)</td><td>Lots</td><td>Lots (SSLOTS)</td></tr><tr><td>Nonconformities</td><td>Nonconformities (OSNCHD)</td><td>Tasks</td><td>Task Plans (WSTASK)</td></tr><tr><td>NonconformityObservations</td><td>Observations tab</td><td>TaskChecklists</td><td>Task Plan Checklist tab</td></tr></table><div class="note">REST entities are listed in Swagger; OData entities are not, so always start from the Service document.</div></div>
<div class="bottom">
<div class="box" style="border-color:#1a5f7a"><h2 style="color:#1a5f7a">10a. Integration flow</h2><div class="flow" style="flex-wrap:wrap;row-gap:4px"><span class="pill">Service doc</span><span class="arr">→</span><span class="pill">$metadata keys</span><span class="arr">→</span><span class="pill">Headers + auth</span><span class="arr">→</span><span class="pill">GET + $filter</span><span class="arr">→</span><span class="pill">PATCH changes</span></div></div>
<div class="box iq"><h2>10b. Consultant tips</h2><ol><li>PATCH, not PUT, for one field</li><li>Page with $top + $skip</li><li>Check the default Dataspy</li><li>Encode # in codes</li></ol></div>
<div class="box" style="border-color:#2d8a5a"><h2 style="color:#2d8a5a">10c. Key points</h2><ul><li>Since 12.1</li><li>6 operations</li><li>4 query options</li></ul></div>
</div></div>'''
build("/workspace/instagram-assets/posts/2026-10-31-linkedin-eam-odata",B,1620,"Rahul Kumar")
